inline ::flatbuffers::Offset<Event> CreateEvent(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    uint64_t sequence_id = 0,
    int32_t bar_index = 0,
    int64_t timestamp_us = 0,
    float delta_t_log = 0.0f,
    float tau_100_log = 0.0f,
    float log_event_velocity = 0.0f,
    float nh_nl_daily = 0.0f,
    bool requires_inference = true,
    uint64_t changed_mask = 0,
    int8_t hmm_state = 0,
    int8_t market_climate = 0,
    const MTS::Schema::IndicatorState *indicators = nullptr,
    float prev_high = 0.0f,
    float prev_low = 0.0f,
    float prev_day_high = 0.0f,
    float prev_day_low = 0.0f,
    float prev_four_bar_high = 0.0f,
    float prev_four_bar_low = 0.0f,
    int8_t side = 0,
    int8_t market_symbol = 0,
    int8_t overnight_exit = 0,
    float open = 0.0f,
    float high = 0.0f,
    float low = 0.0f,
    float close = 0.0f,
    float atr_10 = 0.0f,
    int64_t volume = 0,
    float close_percentile = 0.0f,
    float volume_ratio_percent = 0.0f,
    float volume_imbalance = 0.0f,
    const MTS::Schema::ObservationData *observation = nullptr,
    const MTS::Schema::AsymmetryContext *asymmetry_context = nullptr) {
  EventBuilder builder_(_fbb);
  builder_.add_volume(volume);
  builder_.add_changed_mask(changed_mask);
  builder_.add_timestamp_us(timestamp_us);
  builder_.add_sequence_id(sequence_id);
  builder_.add_asymmetry_context(asymmetry_context);
  builder_.add_observation(observation);
  builder_.add_volume_imbalance(volume_imbalance);
  builder_.add_volume_ratio_percent(volume_ratio_percent);
  builder_.add_close_percentile(close_percentile);
  builder_.add_atr_10(atr_10);
  builder_.add_close(close);
  builder_.add_low(low);
  builder_.add_high(high);
  builder_.add_open(open);
  builder_.add_prev_four_bar_low(prev_four_bar_low);
  builder_.add_prev_four_bar_high(prev_four_bar_high);
  builder_.add_prev_day_low(prev_day_low);
  builder_.add_prev_day_high(prev_day_high);
  builder_.add_prev_low(prev_low);
  builder_.add_prev_high(prev_high);
  builder_.add_indicators(indicators);
  builder_.add_nh_nl_daily(nh_nl_daily);
  builder_.add_log_event_velocity(log_event_velocity);
  builder_.add_tau_100_log(tau_100_log);
  builder_.add_delta_t_log(delta_t_log);
  builder_.add_bar_index(bar_index);
  builder_.add_overnight_exit(overnight_exit);
  builder_.add_market_symbol(market_symbol);
  builder_.add_side(side);
  builder_.add_market_climate(market_climate);
  builder_.add_hmm_state(hmm_state);
  builder_.add_requires_inference(requires_inference);
  return builder_.Finish();
}

